from z3 import *
import itertools

def solve_ramsey():
    n = 20
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((i, j))

    edge_vars = {}
    for i, j in edges:
        edge_vars[(i, j)] = Int(f'e_{i}_{j}')

    solver = Solver()

    # Edge variables are 0 or 1
    for var in edge_vars.values():
        solver.add(Or(var == 0, var == 1))

    # No red K5 (0)
    # For every subset of 5 vertices, at least one edge must be 1
    for subset in itertools.combinations(range(n), 5):
        red_edges = []
        for i, j in itertools.combinations(subset, 2):
            red_edges.append(edge_vars[(i, j)] == 0)
        solver.add(Not(And(*red_edges)))

    # No blue K4 (1)
    # For every subset of 4 vertices, at least one edge must be 0
    for subset in itertools.combinations(range(n), 4):
        blue_edges = []
        for i, j in itertools.combinations(subset, 2):
            blue_edges.append(edge_vars[(i, j)] == 1)
        solver.add(Not(And(*blue_edges)))

    if solver.check() == sat:
        model = solver.model()
        result = []
        for i, j in edges:
            result.append(model[edge_vars[(i, j)]].as_long())
        return result
    else:
        return None

result = solve_ramsey()
print(result)

import random

def solve_ramsey_local_search(n, max_iter=100000):
    # Initialize with random coloring
    num_edges = n * (n - 1) // 2
    edges = [random.randint(0, 1) for _ in range(num_edges)]

    edge_map = {}
    idx = 0
    for i in range(n):
        for j in range(i + 1, n):
            edge_map[(i, j)] = idx
            idx += 1

    def get_edge(i, j):
        if i > j: i, j = j, i
        return edges[edge_map[(i, j)]]

    def set_edge(i, j, val):
        if i > j: i, j = j, i
        edges[edge_map[(i, j)]] = val

    # Find all cliques
    import itertools
    red_k5s = list(itertools.combinations(range(n), 5))
    blue_k4s = list(itertools.combinations(range(n), 4))

    for _ in range(max_iter):
        # Find all monochromatic cliques
        violations = []

        # Check red K5
        for subset in red_k5s:
            is_red = True
            for i, j in itertools.combinations(subset, 2):
                if get_edge(i, j) != 0:
                    is_red = False
                    break
            if is_red:
                violations.append(subset)

        # Check blue K4
        for subset in blue_k4s:
            is_blue = True
            for i, j in itertools.combinations(subset, 2):
                if get_edge(i, j) != 1:
                    is_blue = False
                    break
            if is_blue:
                violations.append(subset)

        if not violations:
            return edges

        # Pick a random violation and flip a random edge in it
        v = random.choice(violations)
        # Pick a random edge in the violation
        i, j = random.choice(list(itertools.combinations(v, 2)))
        set_edge(i, j, 1 - get_edge(i, j))

    return None

