from pysat.solvers import Glucose3
import itertools

def solve_ramsey_pysat(n):
    solver = Glucose3()

    # Edge variables: 1 to n*(n-1)/2
    edge_vars = {}
    idx = 1
    for i in range(n):
        for j in range(i + 1, n):
            edge_vars[(i, j)] = idx
            idx += 1

    # No red K5 (0)
    # For every subset of 5 vertices, at least one edge must be 1
    # Edge is 0 (red) if variable is True, 1 (blue) if variable is False
    # Wait, let's be careful.
    # Let's say variable x_ij = 1 means edge (i,j) is red (0), x_ij = 0 means edge (i,j) is blue (1).
    # No red K5: For every subset of 5, at least one edge is blue (x_ij = 0).
    # So, for every subset of 5, at least one x_ij must be 0.
    # Clause: (not x_i1j1 or not x_i1j2 or ...)
    for subset in itertools.combinations(range(n), 5):
        clause = []
        for i, j in itertools.combinations(subset, 2):
            clause.append(-edge_vars[(i, j)])
        solver.add_clause(clause)

    # No blue K4 (1)
    # For every subset of 4, at least one edge is red (x_ij = 1).
    # So, for every subset of 4, at least one x_ij must be 1.
    # Clause: (x_i1j1 or x_i1j2 or ...)
    for subset in itertools.combinations(range(n), 4):
        clause = []
        for i, j in itertools.combinations(subset, 2):
            clause.append(edge_vars[(i, j)])
        solver.add_clause(clause)

    if solver.solve():
        model = solver.get_model()
        # model contains values for 1 to num_edges
        # If model[idx-1] > 0, edge is red (0), if < 0, edge is blue (1)
        result = []
        for i in range(n):
            for j in range(i + 1, n):
                val = model[edge_vars[(i, j)] - 1]
                if val > 0:
                    result.append(0)
                else:
                    result.append(1)
        return result
    else:
        return None

